// src/App.js - Updated upload function with duplicate check

// Update the uploadResume function
const uploadResume = async (file) => {
  if (!file) {
    alert('Please select a file first');
    return;
  }

  // Check for duplicate filenames
  const existingFile = resumes.find(r => r.filename === file.name);
  if (existingFile) {
    alert(`File "${file.name}" is already uploaded!`);
    // Reset file input
    document.getElementById('file-upload').value = '';
    setSelectedFile(null);
    return;
  }

  const formData = new FormData();
  formData.append('file', file);

  setLoading(true);
  try {
    const response = await axios.post('/upload-resume/', formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });

    // Add the resume data to the list
    const newResume = {
      id: response.data.resume_id || Date.now().toString(),
      name: response.data.data?.name || 'Unnamed Candidate',
      skills: response.data.data?.skills || [],
      experience: response.data.data?.experience || '',
      education: response.data.data?.education || '',
      filename: file.name,
      match_score: null,
      justification: null,
      matched_skills: [],
      missing_skills: []
    };

    setResumes([...resumes, newResume]);
    alert(`✅ "${file.name}" uploaded and parsed successfully!`);
    setSelectedFile(null);
    // Reset file input
    document.getElementById('file-upload').value = '';
  } catch (error) {
    console.error('Upload error:', error);
    alert('Failed to upload resume: ' + (error.response?.data?.detail || error.message));
  } finally {
    setLoading(false);
  }
};
